export const splitMacroHeader = (str: string): (TMacroHeaderInfo | undefined) => {

	const lMatches = str.match(/^\#([A-Za-z_][A-Za-z0-9_]*)\s*(.*)$/)

	if (defined(lMatches)) {
		return [lMatches[1], lMatches[2]]
	}
	else {
		return undef
	}
}

